        return self._parameters

    @property
    def is_semantic(self) -> bool:
        return self._is_semantic

    @property
    def is_asynchronous(self) -> bool:
        return self._is_asynchronous

    @name.setter
    def name(self, value: str) -> None:
        validate_function_name(value)

        self._name = value

    @skill_name.setter
